def f(x):
    """Returns the number of times x can be divided by 2 before becoming odd, with special handling for negative numbers."""
    if x == 0:
        return 0
    n = abs(x)
    count = 0
    while n % 2 == 0:
        count += 1
        n = n // 2
    return count if x > 0 else min(count + 1, 2)
